const products=rows.map((r,id)=>({id,brand:r[0],name:r[1],model:r[2],cpu:r[3],ram:r[4],storage:r[5],display:r[6],gpu:r[7],price:r[8],extra:r[9]}));
const $=s=>document.querySelector(s), money=n=>'$'+n.toLocaleString('en-US');let brand='All laptops',selected;
const art=p=>`<div class="product-art ${p.gpu.includes('RTX')?'gaming':''}" aria-label="Illustration, not a product photograph"><div class="mini-screen"><span>${p.brand}</span><i></i></div><div class="mini-base"></div><small>ILLUSTRATION</small></div>`;
function render(){const query=$('#search').value.toLowerCase();let list=products.filter(p=>(brand==='All laptops'||p.brand===brand)&&Object.values(p).join(' ').toLowerCase().includes(query));if($('#sort').value!=='featured')list.sort((a,b)=>$('#sort').value==='low'?a.price-b.price:b.price-a.price);$('#count').textContent=`${list.length} laptops · Prices in USD`;$('#products').innerHTML=list.map(p=>`<article><div class="card-top"><span>${p.brand.toUpperCase()}</span><span class="badge">${p.gpu.includes('RTX')?'GAMING':'EVERYDAY'}</span></div>${art(p)}<h3>${p.name}</h3><p class="model">${p.model}</p><div class="specs"><span>${p.cpu}</span><span>${p.ram} · ${p.storage}</span><span>${p.display}</span><span>${p.gpu}</span></div><button class="detail-link" data-detail="${p.id}">View full details ↗</button><div class="card-bottom"><strong>${money(p.price)}<small> USD</small></strong><button class="buy" data-buy="${p.id}">Order now ↗</button></div></article>`).join('')||'<p class="empty">No laptops match your search. Try a different model or brand.</p>';}
$('#filters').innerHTML=['All laptops','ASUS','HP','Lenovo','Dell','Acer','MSI'].map((b,i)=>`<button class="filter ${i===0?'active':''}" aria-pressed="${i===0}">${b}</button>`).join('');$('#filters').onclick=e=>{if(!e.target.matches('button'))return;brand=e.target.textContent;document.querySelectorAll('.filter').forEach(b=>{b.classList.toggle('active',b===e.target);b.setAttribute('aria-pressed',b===e.target)});render()};$('#search').oninput=render;$('#sort').onchange=render;
function order(id){selected=products[id];$('#details').close();$('#order-form').reset();$('#wa-fallback').hidden=true;$('#order-summary').textContent=`${selected.brand} ${selected.name} · ${selected.model} · ${selected.ram} · ${money(selected.price)} USD`;$('#order').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-buy]'),d=e.target.closest('[data-detail]');if(b)order(+b.dataset.buy);if(d){const p=products[+d.dataset.detail];$('#detail-content').innerHTML=`<p class="eyebrow">${p.brand} / FULL SPECIFICATIONS</p><h2>${p.name}</h2><p class="model">${p.model}</p>${art(p)}<dl>${[['Processor',p.cpu],['Memory',p.ram],['Storage',p.storage],['Display',p.display],['Graphics',p.gpu],['Other details',p.extra||'Not specified in supplier list']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><div class="detail-price">${money(p.price)} <small>USD</small></div><p class="privacy">Specifications and prices follow the supplied catalog. Confirm availability and configuration with us before purchase.</p><button class="primary" data-buy="${p.id}">Request this laptop ↗</button>`;$('#details').showModal()}if(e.target.closest('.close'))e.target.closest('dialog').close()});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('#order-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p=selected;const message=`Hello! I would like to order:\n${p.brand} ${p.name} (${p.model})\n${p.cpu} | ${p.ram} | ${p.storage}\n${p.gpu} | ${p.display}\nListed price: ${money(p.price)} USD\n\nName: ${f.get('name').trim()}\nPhone: ${f.get('phone').trim()}\nCity / delivery area: ${f.get('city').trim()}\nAddress: ${f.get('address').trim()||'To be confirmed'}\nNotes: ${f.get('notes').trim()||'None'}\n\nPlease confirm availability, delivery cost and final total.`;const url='https://wa.me/963982759514?text='+encodeURIComponent(message);const a=$('#wa-fallback');a.href=url;a.hidden=false;window.open(url,'_blank','noopener,noreferrer')};render();
